    auto *NewLoad = cast<LoadInst>(Builder.CreateLoad(
        VecTy->getElementType(), GEP, EI->getName() + ".scalar"));

    Align ScalarOpAlignment = computeAlignmentAfterScalarization(
        LI->getAlign(), VecTy->getElementType(), Idx, *DL);
    NewLoad->setAlignment(ScalarOpAlignment);

    replaceValue(*EI, *NewLoad);
  }

  FailureGuard.release();
  return true;
}

/// Try to convert "shuffle (binop), (binop)" with a shared binop operand into
/// "binop (shuffle), (shuffle)".
bool VectorCombine::foldShuffleOfBinops(Instruction &I) {
  auto *VecTy = cast<FixedVectorType>(I.getType());
  BinaryOperator *B0, *B1;
  ArrayRef<int> Mask;
  if (!match(&I, m_Shuffle(m_OneUse(m_BinOp(B0)), m_OneUse(m_BinOp(B1)),
                           m_Mask(Mask))) ||
      B0->getOpcode() != B1->getOpcode() || B0->getType() != VecTy)
    return false;

  // Try to replace a binop with a shuffle if the shuffle is not costly.
  // The new shuffle will choose from a single, common operand, so it may be
  // cheaper than the existing two-operand shuffle.
  SmallVector<int> UnaryMask = createUnaryMask(Mask, Mask.size());
  Instruction::BinaryOps Opcode = B0->getOpcode();
  InstructionCost BinopCost = TTI.getArithmeticInstrCost(Opcode, VecTy);
  InstructionCost ShufCost = TTI.getShuffleCost(
      TargetTransformInfo::SK_PermuteSingleSrc, VecTy, UnaryMask);
  if (ShufCost > BinopCost)
    return false;

  // Check if the operands might introduce undefined behavior when shuffled.
  // Specifically, avoid transformations that could lead to poison values
  // causing undefined behavior in the resulting operation.
  Value *X = B0->getOperand(0), *Y = B0->getOperand(1);
  Value *Z = B1->getOperand(0), *W = B1->getOperand(1);

  // For operations that can produce poison/UB (like srem with zero),
  // we need to be more careful about the transformation.
  if (Opcode == Instruction::SDiv || Opcode == Instruction::UDiv ||
      Opcode == Instruction::SRem || Opcode == Instruction::URem) {
    // Check if any operand is poison or zero, which could cause UB
    if (isa<PoisonValue>(X) || isa<PoisonValue>(Y) || 
        isa<PoisonValue>(Z) || isa<PoisonValue>(W) ||
        (Opcode == Instruction::SDiv || Opcode == Instruction::UDiv ||
         Opcode == Instruction::SRem || Opcode == Instruction::URem)) {
      // For division and remainder operations, we need to ensure that
      // we're not creating a situation where zero divisors or poison
      // values would cause undefined behavior
      if (Opcode == Instruction::SDiv || Opcode == Instruction::UDiv ||
          Opcode == Instruction::SRem || Opcode == Instruction::URem) {
        // This is a conservative approach - if we have any poison values
        // or if we're dealing with potentially problematic operations,
        // don't perform the transformation
        return false;
      }
    }
  }

  // If we have something like "add X, Y" and "add Z, X", swap ops to match.
  if (BinaryOperator::isCommutative(Opcode) && X != Z && Y != W)
    std::swap(X, Y);

  Value *Shuf0, *Shuf1;
  if (X == Z) {
    // shuf (bo X, Y), (bo X, W) --> bo (shuf X), (shuf Y, W)
    Shuf0 = Builder.CreateShuffleVector(X, UnaryMask);
    Shuf1 = Builder.CreateShuffleVector(Y, W, Mask);
  } else if (Y == W) {
    // shuf (bo X, Y), (bo Z, Y) --> bo (shuf X, Z), (shuf Y)
    Shuf0 = Builder.CreateShuffleVector(X, Z, Mask);
    Shuf1 = Builder.CreateShuffleVector(Y, UnaryMask);
  } else {
    return false;
  }

  Value *NewBO = Builder.CreateBinOp(Opcode, Shuf0, Shuf1);
  // Intersect flags from the old binops.
  if (auto *NewInst = dyn_cast<Instruction>(NewBO)) {
    NewInst->copyIRFlags(B0);
    NewInst->andIRFlags(B1);
  }

  // TODO: Add Shuf0/Shuf1 to WorkList?
  replaceValue(I, *NewBO);
  return true;
